/* Sunfall City — layout and overlay styling. The world itself is drawn on canvas;
   these rules place the canvas, the start/pause menus and the toast column. */
html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: #0b0e16;
  font-family: "Segoe UI", Arial, sans-serif;
}
#game {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: crosshair;
}
.overlay {
  position: fixed;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: #f2e9d8;
  text-align: center;
  background: radial-gradient(ellipse at center, rgba(12,16,28,0.82), rgba(4,6,12,0.94));
  z-index: 10;
  user-select: none;
}
.overlay.hidden { display: none; }
.overlay h1 {
  font-size: 64px;
  letter-spacing: 6px;
